pub const fn mel_p1(_: &Ctx) -> f32 {
    0f32
}





pub const fn mel_p2(ctx: &Ctx) -> f32 {
    8f32 + 0.04 * ctx.ability_power + 22f32 * (-1f32 + ctx.level) / 17f32
}





pub const fn mel_p3(ctx: &Ctx) -> f32 {
    0.36 * ctx.ability_power
}





